1	import { Router, type Request } from "express";
2	import type { Db } from "@paperclipai/db";
3	import {
4	  addApprovalCommentSchema,
5	  createApprovalSchema,
6	  requestApprovalRevisionSchema,
7	  resolveApprovalSchema,
8	  resubmitApprovalSchema,
9	} from "@paperclipai/shared";
10	import { validate } from "../middleware/validate.js";
11	import { logger } from "../middleware/logger.js";
12	import {
13	  approvalService,
14	  heartbeatService,
15	  issueApprovalService,
16	  logActivity,
17	  secretService,
18	} from "../services/index.js";
19	import { assertBoard, assertCompanyAccess, getActorInfo } from "./authz.js";
20	import { redactEventPayload } from "../redaction.js";
21	import type { PluginWorkerManager } from "../services/plugin-worker-manager.js";
22	
23	function redactApprovalPayload<T extends { payload: Record<string, unknown> }>(approval: T): T {
24	  return {
25	    ...approval,
26	    payload: redactEventPayload(approval.payload) ?? {},
27	  };
28	}
29	
30	export function approvalRoutes(
31	  db: Db,
32	  options: { pluginWorkerManager?: PluginWorkerManager } = {},
33	) {
34	  const router = Router();
35	  const svc = approvalService(db);
36	  const heartbeat = heartbeatService(db, {
37	    pluginWorkerManager: options.pluginWorkerManager,
38	  });
39	  const issueApprovalsSvc = issueApprovalService(db);
40	  const secretsSvc = secretService(db);
41	  const strictSecretsMode = process.env.PAPERCLIP_SECRETS_STRICT_MODE === "true";
42	
43	  async function requireApprovalAccess(req: Request, id: string) {
44	    const approval = await svc.getById(id);
45	    if (!approval) {
46	      return null;
47	    }
48	    assertCompanyAccess(req, approval.companyId);
49	    return approval;
50	  }
51	
52	  router.get("/companies/:companyId/approvals", async (req, res) => {
53	    const companyId = req.params.companyId as string;
54	    assertCompanyAccess(req, companyId);
55	    const status = req.query.status as string | undefined;
56	    const result = await svc.list(companyId, status);
57	    res.json(result.map((approval) => redactApprovalPayload(approval)));
58	  });
59	
60	  router.get("/approvals/:id", async (req, res) => {
61	    const id = req.params.id as string;
62	    const approval = await svc.getById(id);
63	    if (!approval) {
64	      res.status(404).json({ error: "Approval not found" });
65	      return;
66	    }
67	    assertCompanyAccess(req, approval.companyId);
68	    res.json(redactApprovalPayload(approval));
69	  });
70	
71	  router.post("/companies/:companyId/approvals", validate(createApprovalSchema), async (req, res) => {
72	    const companyId = req.params.companyId as string;
73	    assertCompanyAccess(req, companyId);
74	    const rawIssueIds = req.body.issueIds;
75	    const issueIds = Array.isArray(rawIssueIds)
76	      ? rawIssueIds.filter((value: unknown): value is string => typeof value === "string")
77	      : [];
78	    const uniqueIssueIds = Array.from(new Set(issueIds));
79	    const { issueIds: _issueIds, ...approvalInput } = req.body;
80	    const normalizedPayload =
81	      approvalInput.type === "hire_agent"
82	        ? await secretsSvc.normalizeHireApprovalPayloadForPersistence(
83	            companyId,
84	            approvalInput.payload,
85	            { strictMode: strictSecretsMode },
86	          )
87	        : approvalInput.payload;
88	
89	    const actor = getActorInfo(req);
90	    const approval = await svc.create(companyId, {
91	      ...approvalInput,
92	      payload: normalizedPayload,
93	      requestedByUserId: actor.actorType === "user" ? actor.actorId : null,
94	      requestedByAgentId:
95	        approvalInput.requestedByAgentId ?? (actor.actorType === "agent" ? actor.actorId : null),
96	      status: "pending",
97	      decisionNote: null,
98	      decidedByUserId: null,
99	      decidedAt: null,
100	      updatedAt: new Date(),
101	    });
102	
103	    if (uniqueIssueIds.length > 0) {
104	      await issueApprovalsSvc.linkManyForApproval(approval.id, uniqueIssueIds, {
105	        agentId: actor.agentId,
106	        userId: actor.actorType === "user" ? actor.actorId : null,
107	      });
108	    }
109	
110	    await logActivity(db, {
111	      companyId,
112	      actorType: actor.actorType,
113	      actorId: actor.actorId,
114	      agentId: actor.agentId,
115	      action: "approval.created",
116	      entityType: "approval",
117	      entityId: approval.id,
118	      details: { type: approval.type, issueIds: uniqueIssueIds },
119	    });
120	
121	    res.status(201).json(redactApprovalPayload(approval));
122	  });
123	
124	  router.get("/approvals/:id/issues", async (req, res) => {
125	    const id = req.params.id as string;
126	    const approval = await svc.getById(id);
127	    if (!approval) {
128	      res.status(404).json({ error: "Approval not found" });
129	      return;
130	    }
131	    assertCompanyAccess(req, approval.companyId);
132	    const issues = await issueApprovalsSvc.listIssuesForApproval(id);
133	    res.json(issues);
134	  });
135	
136	  router.post("/approvals/:id/approve", validate(resolveApprovalSchema), async (req, res) => {
137	    assertBoard(req);
138	    const id = req.params.id as string;
139	    if (!(await requireApprovalAccess(req, id))) {
140	      res.status(404).json({ error: "Approval not found" });
141	      return;
142	    }
143	    const decidedByUserId = req.actor.userId ?? "board";
144	    const { approval, applied } = await svc.approve(id, decidedByUserId, req.body.decisionNote);
145	
146	    if (applied) {
147	      const linkedIssues = await issueApprovalsSvc.listIssuesForApproval(approval.id);
148	      const linkedIssueIds = linkedIssues.map((issue) => issue.id);
149	      const primaryIssueId = linkedIssueIds[0] ?? null;
150	
151	      await logActivity(db, {
152	        companyId: approval.companyId,
153	        actorType: "user",
154	        actorId: req.actor.userId ?? "board",
155	        action: "approval.approved",
156	        entityType: "approval",
157	        entityId: approval.id,
158	        details: {
159	          type: approval.type,
160	          requestedByAgentId: approval.requestedByAgentId,
161	          linkedIssueIds,
162	        },
163	      });
164	
165	      if (approval.requestedByAgentId) {
166	        try {
167	          const wakeRun = await heartbeat.wakeup(approval.requestedByAgentId, {
168	            source: "automation",
169	            triggerDetail: "system",
170	            reason: "approval_approved",
171	            payload: {
172	              approvalId: approval.id,
173	              approvalStatus: approval.status,
174	              issueId: primaryIssueId,
175	              issueIds: linkedIssueIds,
176	            },
177	            requestedByActorType: "user",
178	            requestedByActorId: req.actor.userId ?? "board",
179	            contextSnapshot: {
180	              source: "approval.approved",
181	              approvalId: approval.id,
182	              approvalStatus: approval.status,
183	              issueId: primaryIssueId,
184	              issueIds: linkedIssueIds,
185	              taskId: primaryIssueId,
186	              wakeReason: "approval_approved",
187	            },
188	          });
189	
190	          await logActivity(db, {
191	            companyId: approval.companyId,
192	            actorType: "user",
193	            actorId: req.actor.userId ?? "board",
194	            action: "approval.requester_wakeup_queued",
195	            entityType: "approval",
196	            entityId: approval.id,
197	            details: {
198	              requesterAgentId: approval.requestedByAgentId,
199	              wakeRunId: wakeRun?.id ?? null,
200	              linkedIssueIds,
201	            },
202	          });
203	        } catch (err) {
204	          logger.warn(
205	            {
206	              err,
207	              approvalId: approval.id,
208	              requestedByAgentId: approval.requestedByAgentId,
209	            },
210	            "failed to queue requester wakeup after approval",
211	          );
212	          await logActivity(db, {
213	            companyId: approval.companyId,
214	            actorType: "user",
215	            actorId: req.actor.userId ?? "board",
216	            action: "approval.requester_wakeup_failed",
217	            entityType: "approval",
218	            entityId: approval.id,
219	            details: {
220	              requesterAgentId: approval.requestedByAgentId,
221	              linkedIssueIds,
222	              error: err instanceof Error ? err.message : String(err),
223	            },
224	          });
225	        }
226	      }
227	    }
228	
229	    res.json(redactApprovalPayload(approval));
230	  });
231	
232	  router.post("/approvals/:id/reject", validate(resolveApprovalSchema), async (req, res) => {
233	    assertBoard(req);
234	    const id = req.params.id as string;
235	    if (!(await requireApprovalAccess(req, id))) {
236	      res.status(404).json({ error: "Approval not found" });
237	      return;
238	    }
239	    const decidedByUserId = req.actor.userId ?? "board";
240	    const { approval, applied } = await svc.reject(id, decidedByUserId, req.body.decisionNote);
241	
242	    if (applied) {
243	      await logActivity(db, {
244	        companyId: approval.companyId,
245	        actorType: "user",
246	        actorId: req.actor.userId ?? "board",
247	        action: "approval.rejected",
248	        entityType: "approval",
249	        entityId: approval.id,
250	        details: { type: approval.type },
251	      });
252	    }
253	
254	    res.json(redactApprovalPayload(approval));
255	  });
256	
257	  router.post(
258	    "/approvals/:id/request-revision",
259	    validate(requestApprovalRevisionSchema),
260	    async (req, res) => {
261	      assertBoard(req);
262	      const id = req.params.id as string;
263	      if (!(await requireApprovalAccess(req, id))) {
264	        res.status(404).json({ error: "Approval not found" });
265	        return;
266	      }
267	      const decidedByUserId = req.actor.userId ?? "board";
268	      const approval = await svc.requestRevision(id, decidedByUserId, req.body.decisionNote);
269	
270	      await logActivity(db, {
271	        companyId: approval.companyId,
272	        actorType: "user",
273	        actorId: req.actor.userId ?? "board",
274	        action: "approval.revision_requested",
275	        entityType: "approval",
276	        entityId: approval.id,
277	        details: { type: approval.type },
278	      });
279	
280	      res.json(redactApprovalPayload(approval));
281	    },
282	  );
283	
284	  router.post("/approvals/:id/resubmit", validate(resubmitApprovalSchema), async (req, res) => {
285	    const id = req.params.id as string;
286	    const existing = await svc.getById(id);
287	    if (!existing) {
288	      res.status(404).json({ error: "Approval not found" });
289	      return;
290	    }
291	    assertCompanyAccess(req, existing.companyId);
292	
293	    if (req.actor.type === "agent" && req.actor.agentId !== existing.requestedByAgentId) {
294	      res.status(403).json({ error: "Only requesting agent can resubmit this approval" });
295	      return;
296	    }
297	
298	    const normalizedPayload = req.body.payload
299	      ? existing.type === "hire_agent"
300	        ? await secretsSvc.normalizeHireApprovalPayloadForPersistence(
301	            existing.companyId,
302	            req.body.payload,
303	            { strictMode: strictSecretsMode },
304	          )
305	        : req.body.payload
306	      : undefined;
307	    const approval = await svc.resubmit(id, normalizedPayload);
308	    const actor = getActorInfo(req);
309	    await logActivity(db, {
310	      companyId: approval.companyId,
311	      actorType: actor.actorType,
312	      actorId: actor.actorId,
313	      agentId: actor.agentId,
314	      action: "approval.resubmitted",
315	      entityType: "approval",
316	      entityId: approval.id,
317	      details: { type: approval.type },
318	    });
319	    res.json(redactApprovalPayload(approval));
320	  });
321	
322	  router.get("/approvals/:id/comments", async (req, res) => {
323	    const id = req.params.id as string;
324	    const approval = await svc.getById(id);
325	    if (!approval) {
326	      res.status(404).json({ error: "Approval not found" });
327	      return;
328	    }
329	    assertCompanyAccess(req, approval.companyId);
330	    const comments = await svc.listComments(id);
331	    res.json(comments);
332	  });
333	
334	  router.post("/approvals/:id/comments", validate(addApprovalCommentSchema), async (req, res) => {
335	    const id = req.params.id as string;
336	    const approval = await svc.getById(id);
337	    if (!approval) {
338	      res.status(404).json({ error: "Approval not found" });
339	      return;
340	    }
341	    assertCompanyAccess(req, approval.companyId);
342	    const actor = getActorInfo(req);
343	    const comment = await svc.addComment(id, req.body.body, {
344	      agentId: actor.agentId ?? undefined,
345	      userId: actor.actorType === "user" ? actor.actorId : undefined,
346	    });
347	
348	    await logActivity(db, {
349	      companyId: approval.companyId,
350	      actorType: actor.actorType,
351	      actorId: actor.actorId,
352	      agentId: actor.agentId,
353	      action: "approval.comment_added",
354	      entityType: "approval",
355	      entityId: approval.id,
356	      details: { commentId: comment.id },
357	    });
358	
359	    res.status(201).json(comment);
360	  });
361	
362	  return router;
363	}
